<?php
namespace Modules\Inventory\Models;
use Illuminate\Database\Eloquent\Model;
class InventoryProposal extends Model { protected $table='inventory_proposals'; protected $fillable=['type','status','title','description','unit_id','warehouse_id','created_by','proposed_by_user_id','proposed_by_username','proposed_by_display_name','nganh_code','proposal_code','decided_by','decision_number','decision_note','decision_issuing_level','decision_signer','decided_at','completed_at','print_mode','signature_method','signature_path','printed_at']; protected $casts=['decided_at'=>'datetime','completed_at'=>'datetime','printed_at'=>'datetime']; protected static function booted(){static::creating(function(self $proposal){if($proposal->type==='RECALL'){ $warehouseId=request()->input('warehouse_id'); abort_unless($warehouseId&&InventoryWarehouse::where('active',true)->whereKey($warehouseId)->exists(),422,'Đề xuất thu hồi phải chọn kho nhận.'); $proposal->warehouse_id=$warehouseId;}});static::updated(function(self $proposal){if($proposal->type!=='RECALL'||!$proposal->wasChanged('status')||!in_array($proposal->status,['APPROVED','COMPLETED'],true)||$proposal->getOriginal('status')!=='PENDING')return;$warehouse=InventoryWarehouse::find($proposal->warehouse_id);if(!$warehouse)return;foreach($proposal->items()->with(['asset.material','material'])->get() as $item){$quantity=max(1,(int)$item->quantity);$source=$item->asset?:$item->material;if(!$source)continue;$code=$source instanceof InventoryAsset?($source->material?->code?:$source->asset_code):$source->code;$name=$source->name;$unit=$source->unit;$before=(int)$source->quantity;$remaining=max(0,$before-$quantity);if($source instanceof InventoryAsset){$source->update(['quantity'=>$remaining]);}else{$source->update(['quantity'=>$remaining,'classroom_id'=>$remaining>0?$source->classroom_id:null]);}$warehouseItem=InventoryWarehouseItem::firstOrCreate(['warehouse_id'=>$warehouse->id,'code'=>$code],['material_id'=>$source instanceof InventoryAsset?$source->material_id:$source->id,'name'=>$name,'unit'=>$unit,'quantity'=>0,'minimum_quantity'=>0]);$warehouseItem->increment('quantity',min($quantity,$before));}});} public function items(){return $this->hasMany(InventoryProposalItem::class,'proposal_id');} public function unit(){return $this->belongsTo(\Modules\Unit\Models\Unit::class);} public function warehouse(){return $this->belongsTo(InventoryWarehouse::class,'warehouse_id');} public function decidedBy(){return $this->belongsTo(\App\Models\User::class,'decided_by');} }
